# -*- coding: utf-8 -*-
# 第 11 批（C2）：危險性機械及設備安全檢查規則（OSH-53）第48條～第100條（補題）
# ※ 四個選項刻意寫成相近長度。
L = "OSH-53"
Q = [
(L,"第48條",1,"營建用升降機-定期效期",
 "營建用升降機經定期檢查合格者，其使用有效期限最長為何？",
 ["於原檢查合格證上簽署，註明使用有效期限，最長為一年","於原檢查合格證上簽署，註明使用有效期限，最長為二年","應重新核發檢查合格證，註明使用有效期限最長三年","應重新核發檢查合格證，註明使用有效期限最長五年"],"a",
 "第48條：檢查機構對定期檢查合格之營建用升降機，應於原檢查合格證上簽署，註明使用有效期限，最長為一年；檢查員應填報營建用升降機定期檢查結果報告表，並將結果通知雇主。第46條：竣工檢查合格證有效期限亦最長為一年。",
 "How long at most is a construction lift valid after passing its periodic inspection?",
 ["The original certificate is endorsed with a valid period of at most one year","The original certificate is endorsed with a valid period of at most two years","A new inspection certificate is issued with a valid period of at most three years","A new inspection certificate is issued with a valid period of at most five years"],
 "Article 48."),

(L,"第49條",2,"營建用升降機-變更備查",
 "雇主變更營建用升降機之哪些部分時，應檢附圖件報請檢查機構備查？",
 ["捲揚機、原動機、鋼索或吊鏈、制動裝置；但材質、規格及尺寸不變者，不在此限","搬器、配重、升降路塔、導軌支持塔或拉索；但材質、規格及尺寸不變者不在此限","操作人員、保養廠商及設置場所名稱；但材質、規格及尺寸不變者不在此限","塗裝顏色、標示牌與照明燈具規格；但材質、規格及尺寸不變者不在此限"],"a",
 "第49條：雇主變更營建用升降機之捲揚機、原動機、鋼索或吊鏈、制動裝置之一時，應檢附變更部分之圖件報請檢查機構備查；但材質、規格及尺寸不變者，不在此限。變更搬器、配重、升降路塔、導軌支持塔或拉索者，則應依第50條申請變更檢查。",
 "Which changes to a construction lift need only be filed with drawings for recordation?",
 ["The winch, prime mover, wire rope or chain and braking device, unless material, specification and size are unchanged","The carrier, counterweight, hoistway tower, guide rail support tower or guys, unless material, spec and size are unchanged","The operator, the maintenance contractor and the name of the site, unless material, specification and size are unchanged","The paint colour, signboards and the specification of lighting, unless material, specification and size are unchanged"],
 "Article 49."),

(L,"第50條",2,"營建用升降機-變更檢查",
 "雇主變更營建用升降機之哪些部分時，應申請變更檢查？",
 ["變更搬器、配重、升降路塔、導軌支持塔或拉索時，應填具變更檢查申請書及圖件申請變更檢查","變更捲揚機、原動機、鋼索或吊鏈或制動裝置時，應填具變更檢查申請書及圖件申請變更檢查","變更設置場所、使用單位或操作人員時，應填具變更檢查申請書及圖件申請變更檢查","變更搬器內照明、警報裝置或標示牌時，應填具變更檢查申請書及圖件申請變更檢查"],"a",
 "第50條：雇主變更營建用升降機之搬器、配重、升降路塔、導軌支持塔或拉索時，應填具變更檢查申請書及變更部分之圖件向檢查機構申請變更檢查；合格者於原合格證記載檢查日期、變更部分及檢查結果；變更檢查準用第44條及第45條規定。",
 "Which alterations to a construction lift require an alteration inspection?",
 ["Altering the carrier, counterweight, hoistway tower, guide rail support tower or guys requires an alteration inspection with drawings","Altering the winch, the prime mover, the wire rope or chain or the braking device requires an alteration inspection with drawings","Altering the site, the using unit or the operator of the lift requires an alteration inspection application with drawings attached","Altering the lighting in the carrier, the alarm device or signboards requires an alteration inspection with drawings attached"],
 "Article 50."),

(L,"第51條",2,"營建用升降機-重新檢查",
 "營建用升降機停用超過檢查合格證有效期限一年以上，恢復使用前應如何辦理？",
 ["應填具重新檢查申請書申請重新檢查，合格者於原合格證記載檢查日期結果及有效期限最長一年","應填具重新檢查申請書申請重新檢查，合格者於原合格證記載檢查日期結果及有效期限最長二年","應由製造人重新申請型式檢查，取得製造設施型式檢查合格證明後再辦理竣工檢查始得使用","應報請當地主管機關備查後即得恢復使用，並於恢復使用後六個月內補辦定期檢查之手續"],"a",
 "第51條：雇主對於停用超過檢查合格證有效期限一年以上之營建用升降機，恢復使用前應填具重新檢查申請書向檢查機構申請重新檢查；合格者於原檢查合格證上記載檢查日期、檢查結果及使用有效期限，最長為一年；重新檢查準用第44條及第45條規定。",
 "Before a construction lift idle over a year past its certificate's expiry is used again, what is required?",
 ["Apply for re-inspection; on passing, the original certificate is endorsed with date, result and a valid period of at most one year","Apply for re-inspection; on passing, the original certificate is endorsed with date, result and a valid period of at most two years","The maker must apply again for a type inspection and obtain the facility certificate before a completion inspection allows use","Recordation with the local competent authority suffices for resumption, the periodic inspection being completed within six months"],
 "Article 51."),

(L,"第52條",2,"營建用提升機-型式檢查",
 "營建用提升機之製造或修改，其型式檢查應由何人於何時申請？",
 ["由製造人於事前填具型式檢查申請書，檢附相關書件向所在地檢查機構申請檢查","由雇主於設置完成後填具型式檢查申請書，檢附相關書件向當地檢查機構申請","由所有人於使用滿一年後填具型式檢查申請書，檢附書件向檢查機構申請檢查","由代行檢查機構逕行實施型式檢查後，將結果函報中央主管機關核備即可"],"a",
 "第52條：營建用提升機之製造或修改，其製造人應於事前填具型式檢查申請書，檢附型式、強度計算基準及組配圖、製造過程之必要檢驗設備概要、主任設計者及施工負責人學經歷概要，向所在地檢查機構申請檢查；品管品保準用第11條；未經檢查合格不得製造或修改。",
 "Who must apply for the type inspection of a construction hoist, and when?",
 ["The manufacturer applies in advance with the required documents to the inspection agency where it is located","The employer applies after installation is complete with the required documents to the local inspection agency","The owner applies after a full year of use with the required documents to the local inspection agency","The designated inspection body performs the type inspection itself and merely reports it to the authority"],
 "Article 52."),

(L,"第53條",2,"營建用提升機-竣工檢查",
 "雇主申請營建用提升機竣工檢查時，應檢附哪些文件？",
 ["製造設施型式檢查合格證明、設置場所平面圖及基礎概要、營建用提升機明細表、強度計算基準及組配圖","製造設施型式檢查合格證明、設置場所四周狀況圖、操作人員名冊、荷重試驗紀錄及安定性試驗結果報告","建造執照與結構計算書、假設工程配置圖、鄰房現況鑑定報告、交通維持計畫書及施工安全評估報告書","工廠登記證與公司登記證明、勞工保險投保名冊、自動檢查計畫、緊急應變計畫及承攬管理計畫書等件"],"a",
 "第53條：雇主於營建用提升機設置完成時，應填具竣工檢查申請書，檢附製造設施型式檢查合格證明（外國進口者檢附品管等相關文件）、設置場所平面圖及基礎概要、營建用提升機明細表、強度計算基準及組配圖，向所在地檢查機構申請竣工檢查。",
 "What documents must accompany a construction hoist's completion inspection application?",
 ["The facility type inspection certificate, the site plan with foundation outline, the hoist specification table, and the strength basis and assembly drawing","The facility type inspection certificate, a drawing of the site surroundings, the operator roster, load test records and the stability test result report","The building permit and structural calculations, temporary works layout, an adjoining building survey, the traffic maintenance plan and safety evaluation report","The factory and company registrations, the labor insurance roster, the automatic inspection plan, the emergency response plan and the contractor management plan"],
 "Article 53."),

(L,"第54條",2,"營建用提升機-竣工項目",
 "營建用提升機竣工檢查之項目及荷重試驗內容為何？",
 ["項目為構造與性能之檢查、荷重試驗及其他必要之檢查；荷重試驗為積載荷重一點二倍之荷重置於搬器上實施升降動作試驗","項目為構造與性能之檢查、荷重試驗及安定性試驗；荷重試驗為積載荷重一點二五倍之荷重置於搬器上實施升降動作試驗","項目為構造與性能之檢查、荷重試驗及耐壓試驗；荷重試驗為額定荷重一點二七倍之荷重置於吊具上實施吊升旋轉試驗","項目為外觀檢查及構造檢查；荷重試驗為積載荷重二分之一之荷重置於搬器上於最低速率下實施升降及橫行動作試驗"],"a",
 "第54條：營建用提升機竣工檢查項目為構造與性能之檢查、荷重試驗及其他必要之檢查；荷重試驗指將相當於該提升機積載荷重一點二倍之荷重置於搬器上實施升降動作試驗；對外國進口具有相當檢查證明文件者，檢查機構得免除全部或一部之檢查。",
 "What items and load test apply at a construction hoist's completion inspection?",
 ["Structure and performance check, load test and other necessary checks; the load test raises and lowers 1.2 times the carrying load placed on the carrier","Structure and performance check, load test and stability test; the load test raises and lowers 1.25 times the carrying load placed on the carrier","Structure and performance check, load test and pressure test; the load test hoists and slews 1.27 times the rated load placed on the lifting gear","Visual check and structural check only; the load test raises, lowers and traverses half the carrying load on the carrier at the lowest speed"],
 "Article 54."),

(L,"第55條",1,"營建用提升機-檢查通知",
 "檢查機構受理營建用提升機竣工檢查申請後，應通知雇主準備何物？",
 ["應將檢查日期通知雇主，使其準備荷重試驗用荷物及必要之運搬器具","應將檢查日期通知雇主，使其準備安定性試驗用荷物及必要之吊掛器具","應將檢查日期通知雇主，使其準備耐壓試驗用水源及必要之加壓裝置","應將檢查日期通知製造人，使其準備荷重試驗用荷物及運搬之器具"],"a",
 "第55條：檢查機構對雇主申請營建用提升機之竣工檢查，應於受理檢查後將檢查日期通知雇主，使其準備荷重試驗用荷物及必要之運搬器具。第57條第4項：定期檢查之荷重試驗準用本條規定。",
 "After accepting a construction hoist completion inspection application, what must the employer prepare?",
 ["Notify the employer of the date so it prepares the loads for the load test and the necessary conveying gear","Notify the employer of the date so it prepares the loads for the stability test and the necessary rigging gear","Notify the employer of the date so it prepares a water supply for the pressure test and pressurising devices","Notify the maker of the date so that the maker prepares the load test loads and the gear for conveying them"],
 "Article 55."),

(L,"第56條",2,"營建用提升機-合格證",
 "營建用提升機竣工檢查合格後，其檢查合格證有效期限及置掛規定為何？",
 ["檢查機構應發給檢查合格證，有效期限最長為二年；雇主應將合格證或其影本置掛於該提升機明顯處","檢查機構應發給檢查合格證，有效期限最長為一年；雇主應將合格證或其影本置掛於該提升機明顯處","檢查機構應發給檢查合格證，有效期限最長為三年；雇主應將合格證正本送當地主管機關存查備用","檢查機構應發給檢查合格證，有效期限最長為五年；雇主應將合格證存放於工地辦公室備供查閱之"],"a",
 "第56條：檢查機構對竣工檢查合格之營建用提升機，應在明細表上加蓋檢查合格戳記，並在被檢查物體明顯部位打印、漆印或張貼檢查合格標章；發給檢查合格證，其有效期限最長為二年；雇主應將檢查合格證或其影本置掛於該營建用提升機明顯處。",
 "How long is a construction hoist's certificate valid after completion inspection, and where is it posted?",
 ["The agency issues a certificate valid at most two years; the employer posts the certificate or a copy conspicuously on the hoist","The agency issues a certificate valid at most one year; the employer posts the certificate or a copy conspicuously on the hoist","The agency issues a certificate valid at most three years; the employer lodges the original with the local competent authority","The agency issues a certificate valid at most five years; the employer keeps the certificate in the site office for inspection"],
 "Article 56."),

(L,"第57條",2,"營建用提升機-定期檢查",
 "營建用提升機定期檢查之申請期限及荷重試驗內容為何？",
 ["應於合格證有效期限屆滿前一個月申請；荷重試驗為相當積載荷重之荷物置於搬器上實施升降動作試驗","應於合格證有效期限屆滿前三個月申請；荷重試驗為積載荷重一點二倍之荷物置於搬器上實施升降試驗","應於合格證有效期限屆滿後一個月內申請；荷重試驗為額定荷重之荷物置於吊具上實施吊升旋轉試驗","應於合格證有效期限屆滿前一年申請；荷重試驗為積載荷重二分之一之荷物置於搬器上實施升降試驗"],"a",
 "第57條：雇主於營建用提升機檢查合格證有效期限屆滿前一個月，應填具定期檢查申請書申請定期檢查，逾期未申請或檢查不合格者不得繼續使用；定期檢查荷重試驗係將相當積載荷重之荷物置於搬器上實施升降動作試驗，但檢查機構認無必要時得免實施。",
 "When must a construction hoist's periodic inspection be applied for, and what is its load test?",
 ["Apply one month before the certificate expires; the load test raises and lowers a load equal to the carrying load on the carrier","Apply three months before the certificate expires; the load test raises and lowers 1.2 times the carrying load on the carrier","Apply within one month after the certificate expires; the load test hoists and slews a load equal to the rated load on the gear","Apply one year before the certificate expires; the load test raises and lowers half the carrying load placed on the carrier"],
 "Article 57."),

(L,"第58條",1,"營建用提升機-定期效期",
 "營建用提升機經定期檢查合格者，其使用有效期限最長為何？",
 ["於原檢查合格證上簽署，註明使用有效期限，最長為二年","於原檢查合格證上簽署，註明使用有效期限，最長為一年","應重新核發檢查合格證，註明使用有效期限最長三年","應重新核發檢查合格證，註明使用有效期限最長五年"],"a",
 "第58條：檢查機構對定期檢查合格之營建用提升機，應於原檢查合格證上簽署，註明使用有效期限，最長為二年；檢查員於實施定期檢查後，應填報營建用提升機定期檢查結果報告表，並將定期檢查結果通知雇主。",
 "How long at most is a construction hoist valid after passing its periodic inspection?",
 ["The original certificate is endorsed with a valid period of at most two years","The original certificate is endorsed with a valid period of at most one year","A new inspection certificate is issued with a valid period of at most three years","A new inspection certificate is issued with a valid period of at most five years"],
 "Article 58."),

(L,"第59條",2,"營建用提升機-變更備查",
 "關於營建用提升機之變更報備及合格證註銷，下列敘述何者正確？",
 ["變更原動機、絞車、鋼索或吊鏈、制動裝置應檢附圖件報請備查；導軌或升降路高度變更為未滿二十公尺者，應報請檢查機構認定後註銷合格證","變更原動機、絞車、鋼索或吊鏈、制動裝置應申請變更檢查；導軌或升降路高度變更為未滿三十公尺者，應報請檢查機構認定後註銷合格證","變更導軌、升降路或搬器等部分僅需報請備查；導軌或升降路高度變更為未滿十公尺者，應報請中央主管機關核准後註銷其檢查合格證","變更任何部分均應報請備查並重新核發合格證；導軌或升降路高度變更為未滿五公尺者，得由雇主自行註銷合格證並函知檢查機構"],"a",
 "第59條：雇主變更營建用提升機之原動機、絞車、鋼索或吊鏈、制動裝置之一時，應檢附變更部分之圖件報請檢查機構備查，但材質、規格及尺寸不變者不在此限；變更導軌或升降路之高度為未滿二十公尺者，應報請檢查機構認定後註銷其檢查合格證。第3條第5款：本規則適用於導軌或升降路高度在二十公尺以上之營建用提升機。",
 "Which statement about recordation and certificate cancellation for a construction hoist is correct?",
 ["Changing the prime mover, winch, rope or chain or brake needs recordation with drawings; if the guide rail or hoistway height falls below twenty metres the certificate is cancelled","Changing the prime mover, winch, rope or chain or brake needs an alteration inspection; if the guide rail or hoistway height falls below thirty metres the certificate is cancelled","Changing the guide rail, hoistway or carrier needs only recordation; if the guide rail or hoistway height falls below ten metres the central competent authority cancels the certificate","Any change whatever needs recordation and a reissued certificate; if the guide rail or hoistway height falls below five metres the employer may cancel the certificate itself"],
 "Article 59; cf. Article 3."),

(L,"第60條",2,"營建用提升機-變更檢查",
 "雇主變更營建用提升機之哪些部分時，應申請變更檢查？",
 ["變更導軌、升降路或搬器時，應填具變更檢查申請書及變更部分之圖件申請變更檢查","變更原動機、絞車、鋼索或制動裝置時，應填具變更檢查申請書及圖件申請變更檢查","變更設置場所、使用單位或操作人員時，應填具變更檢查申請書及圖件申請檢查","變更搬器內標示、照明或警報裝置時，應填具變更檢查申請書及圖件申請檢查"],"a",
 "第60條：雇主變更營建用提升機之導軌、升降路或搬器時，應填具變更檢查申請書及變更部分之圖件向檢查機構申請變更檢查；合格者於原合格證記載檢查日期、變更部分及檢查結果；變更檢查準用第54條及第55條規定。",
 "Which alterations to a construction hoist require an alteration inspection?",
 ["Altering the guide rail, the hoistway or the carrier requires an alteration inspection application with drawings attached","Altering the prime mover, winch, wire rope or braking device requires an alteration inspection application with drawings","Altering the site, the using unit or the operator of the hoist requires an alteration inspection application with drawings","Altering signage, lighting or the alarm device in the carrier requires an alteration inspection application with drawings"],
 "Article 60."),

(L,"第61條",2,"營建用提升機-重新檢查",
 "營建用提升機停用超過檢查合格證有效期限一年以上擬恢復使用時，應如何辦理？",
 ["應填具重新檢查申請書申請重新檢查，合格者於原合格證記載檢查日期結果及有效期限最長二年","應填具重新檢查申請書申請重新檢查，合格者於原合格證記載檢查日期結果及有效期限最長一年","應由製造人重新申請型式檢查取得合格證明後，再由雇主重新辦理竣工檢查始得恢復使用","應報請當地主管機關核備後即得恢復使用，並於恢復使用後三個月內補辦定期檢查手續"],"a",
 "第61條：雇主對於停用超過檢查合格證有效期限一年以上之營建用提升機，擬恢復使用時應填具重新檢查申請書向檢查機構申請重新檢查；合格者於原檢查合格證上記載檢查日期、檢查結果及使用有效期限，最長為二年；重新檢查準用第54條及第55條規定。",
 "How is a construction hoist idle over a year beyond its certificate's expiry returned to use?",
 ["Apply for re-inspection; on passing, the original certificate is endorsed with date, result and a valid period of at most two years","Apply for re-inspection; on passing, the original certificate is endorsed with date, result and a valid period of at most one year","The maker must first obtain a fresh type inspection certificate, after which the employer redoes the completion inspection","Recordation with the local competent authority allows resumption, the periodic inspection following within three months"],
 "Article 61."),

(L,"第62條",2,"吊籠-型式檢查",
 "吊籠之製造或修改，其型式檢查之申請人及未經檢查合格之效果為何？",
 ["應由製造人於事前向所在地檢查機構申請；未經檢查合格不得製造或修改，但與業經合格之型式及條件相同者不在此限","應由雇主於使用前向當地檢查機構申請；未經檢查合格不得使用，但外國進口之吊籠得逕行使用而免辦型式檢查","應由所有人於製造完成後向檢查機構申請；未經檢查合格仍得製造，僅不得出租或出售予其他事業單位使用","應由代行檢查機構逕行實施並報中央主管機關；未經檢查合格得先行製造，於竣工檢查前補辦型式檢查即可"],"a",
 "第62條：吊籠之製造或修改，其製造人應於事前填具型式檢查申請書，檢附型式、強度計算基準及組配圖等書件向所在地檢查機構申請檢查；品管、品保措施、設備及人員準用第11條；未經檢查合格，不得製造或修改，但與業經型式檢查合格之型式及條件相同者，不在此限。",
 "Who applies for a suspended access cradle's type inspection, and what follows without passing it?",
 ["The maker applies in advance to the local agency; without passing it may not be made or modified, except for a type and conditions already passed","The employer applies before use to the local agency; without passing it may not be used, though imported cradles are exempt from type inspection","The owner applies after manufacture to the agency; without passing it may still be made and only leasing or selling it to others is prohibited","The designated body inspects on its own and reports to the authority; without passing it may be made and the papers completed before use"],
 "Article 62."),

(L,"第63條",2,"吊籠-使用檢查",
 "雇主於吊籠製造完成使用前或外國進口使用前，申請使用檢查應檢附哪些文件？",
 ["製造設施型式檢查合格證明、吊籠明細表、強度計算基準及組配圖、設置固定方式","製造設施型式檢查合格證明、操作人員名冊、荷重試驗紀錄及安定性試驗紀錄","設置場所四周狀況圖、鄰房現況鑑定報告、外牆清洗計畫及交通維持計畫書","工廠登記證影本、勞工保險投保名冊、自動檢查計畫及職業安全衛生管理計畫"],"a",
 "第63條：雇主於吊籠製造完成使用前或從外國進口使用前，應填具吊籠使用檢查申請書，檢附製造設施型式檢查合格證明（外國進口者檢附品管等相關文件）、吊籠明細表、強度計算基準及組配圖、設置固定方式，向當地檢查機構申請使用檢查。第64條：使用檢查項目為構造與性能之檢查、荷重試驗及其他必要之檢查。",
 "What documents must accompany a use inspection application for a suspended access cradle?",
 ["The facility type inspection certificate, the cradle specification table, the strength calculation basis and assembly drawing, and the method of fixing it","The facility type inspection certificate, the roster of operators, the records of the load test performed and the records of the stability test","A drawing of the surroundings of the site, an adjoining building survey report, the facade cleaning plan and the traffic maintenance plan","A copy of the factory registration, the labor insurance roster, the automatic inspection plan and the occupational safety management plan"],
 "Article 63."),

(L,"第65條",1,"吊籠-檢查通知",
 "檢查機構受理吊籠使用檢查申請後，應通知雇主辦理何事？",
 ["應將檢查日期通知雇主，使其將該吊籠移於易檢查之位置，並準備荷重試驗用荷物及必要之運搬器具","應將檢查日期通知雇主，使其將該吊籠拆卸分解至零件狀態，並準備非破壞檢查所需之各項儀器設備","應將檢查日期通知製造人，使其將該吊籠運回工廠檢查，並準備安定性試驗用荷物及必要之器具","應將檢查日期公告於指定資訊網站，由檢查機構自行將吊籠移至易檢查位置並準備試驗用之荷物"],"a",
 "第65條：檢查機構對雇主申請吊籠之使用檢查，應於受理檢查後，將檢查日期通知雇主，使其將該吊籠移於易檢查之位置，並準備荷重試驗用荷物及必要之運搬器具。第64條第2項：荷重試驗係將相當於積載荷重之荷物置於工作台上，於額定速率下實施上升，或於容許下降速率下實施下降等動作試驗。",
 "After accepting a cradle use inspection application, what must the inspection agency have done?",
 ["Notify the employer of the date so it moves the cradle to a position easy to inspect and prepares the load test loads and conveying gear","Notify the employer of the date so it dismantles the cradle completely into parts and prepares the instruments for non-destructive testing","Notify the maker of the date so the maker returns the cradle to the factory for inspection and prepares stability test loads and gear","Publish the date on the designated website, the inspection agency itself moving the cradle to an accessible spot and preparing the loads"],
 "Article 65; see Article 64."),

(L,"第66條",2,"吊籠-合格證",
 "吊籠使用檢查合格後，其檢查合格證之有效期限及置掛位置為何？",
 ["發給使用檢查結果報告表及檢查合格證，有效期限最長為一年；雇主應將合格證或影本置掛於該吊籠工作台上明顯處","發給使用檢查結果報告表及檢查合格證，有效期限最長為二年；雇主應將合格證或影本置掛於該吊籠工作台上明顯處","發給使用檢查結果報告表及檢查合格證，有效期限最長為三年；雇主應將合格證正本送交當地主管機關存查備用","發給使用檢查結果報告表及檢查合格證，有效期限最長為五年；雇主應將合格證存放於公司總部檔案室備供查閱"],"a",
 "第66條：檢查機構對使用檢查合格之吊籠，應在吊籠明細表上加蓋檢查合格戳記，並在被檢查物體明顯部位打印、漆印或張貼檢查合格標章；發給使用檢查結果報告表及檢查合格證，其有效期限最長為一年；雇主應將檢查合格證或其影本置掛於該吊籠之工作台上明顯處。",
 "How long is a cradle's certificate valid after the use inspection, and where must it be posted?",
 ["A result report and a certificate valid at most one year issue; the employer posts the certificate or a copy conspicuously on the cradle platform","A result report and a certificate valid at most two years issue; the employer posts the certificate or a copy conspicuously on the cradle platform","A result report and a certificate valid at most three years issue; the employer lodges the original certificate with the local competent authority","A result report and a certificate valid at most five years issue; the employer keeps the certificate in the head office archive for inspection"],
 "Article 66."),

(L,"第67條",2,"吊籠-定期檢查",
 "吊籠定期檢查之申請期限及檢查內容為何？",
 ["應於合格證有效期限屆滿前一個月申請；就構造、性能、荷重試驗及其他必要項目實施，荷重試驗準用使用檢查之規定","應於合格證有效期限屆滿前三個月申請；僅就外觀及安全裝置實施檢查，荷重試驗一律免除而無須另行實施之","應於合格證有效期限屆滿後一個月內申請；就構造與性能實施檢查，荷重試驗改由雇主自行辦理並紀錄留存備查","應於合格證有效期限屆滿前一年申請；就構造、性能及耐壓試驗實施檢查，並須同時實施安定性試驗與氣密試驗"],"a",
 "第67條：雇主於吊籠檢查合格證有效期限屆滿前一個月，應填具定期檢查申請書向檢查機構申請定期檢查，逾期未申請檢查或檢查不合格者不得繼續使用；定期檢查應就該吊籠各部分之構造、性能、荷重試驗及其他必要項目實施檢查；荷重試驗準用第64條第2項及第15條規定。",
 "When must a cradle's periodic inspection be applied for, and what does it cover?",
 ["Apply one month before the certificate expires; structure, performance, a load test and other necessary items, the load test following the use inspection rules","Apply three months before the certificate expires; only appearance and safety devices are checked, and the load test is dispensed with in every case","Apply within one month after the certificate expires; structure and performance are checked, the employer conducting and recording the load test itself","Apply one year before the certificate expires; structure, performance and a pressure test are checked, together with stability and airtightness tests"],
 "Article 67."),

(L,"第68條",1,"吊籠-定期效期",
 "吊籠經定期檢查合格者，其使用有效期限最長為何？檢查員應辦理何事？",
 ["於原檢查合格證上簽署註明有效期限最長一年；並應填報吊籠定期檢查結果報告表通知雇主","於原檢查合格證上簽署註明有效期限最長二年；並應填報吊籠定期檢查結果報告表通知雇主","應重新核發檢查合格證註明有效期限最長三年；並應將檢查結果函報中央主管機關備查","應重新核發檢查合格證註明有效期限最長五年；並由雇主自行記載檢查結果留存備查用"],"a",
 "第68條：檢查機構對定期檢查合格之吊籠，應於原檢查合格證上簽署，註明使用有效期限，最長為一年；檢查員於實施定期檢查後，應填報吊籠定期檢查結果報告表，並將定期檢查結果通知雇主。",
 "How long at most is a cradle valid after periodic inspection, and what must the inspector do?",
 ["The original certificate is endorsed for at most one year; the inspector files a periodic inspection result report and notifies the employer","The original certificate is endorsed for at most two years; the inspector files a periodic inspection result report and notifies the employer","A new certificate is issued for at most three years; the inspector reports the inspection result to the central competent authority for record","A new certificate is issued for at most five years; the employer records the inspection result itself and keeps it on file for reference"],
 "Article 68."),

(L,"第69條",2,"吊籠-變更檢查",
 "雇主變更吊籠之哪些部分時，應申請變更檢查？其例外為何？",
 ["變更工作台、吊臂及其他構造部分、升降裝置、制動裝置、控制裝置、鋼索或吊鏈、固定方式時應申請；其中升降制動控制裝置及鋼索吊鏈之材質規格尺寸不變者除外","變更工作台、吊臂及其他構造部分、升降裝置、制動裝置、控制裝置、鋼索或吊鏈、固定方式時應申請；其中工作台及吊臂之材質規格尺寸不變者亦得免申請變更檢查","僅變更工作台或吊臂時應申請變更檢查，其餘升降裝置、制動裝置、控制裝置、鋼索或吊鏈及固定方式之變更，一律僅需檢附圖件報請檢查機構備查即可","變更任何部分均應申請變更檢查而無例外，且檢查合格後應由檢查機構重新核發檢查合格證，並重新起算其使用有效期限最長一年"],"a",
 "第69條：雇主變更吊籠之工作台、吊臂及其他構造部分、升降裝置、制動裝置、控制裝置、鋼索或吊鏈、固定方式之一時，應填具變更檢查申請書及變更部分之圖件申請變更檢查；但第3款至第6款（升降裝置、制動裝置、控制裝置、鋼索或吊鏈）之變更，材質、規格及尺寸不變者，不在此限。變更檢查準用第64條及第65條。",
 "Which alterations to a cradle require an alteration inspection, and what is the exception?",
 ["The platform, arm and other structural parts, hoisting, braking and control devices, ropes or chains and fixing method; hoisting, braking, control and rope changes are exempt if material, spec and size are unchanged","The platform, arm and other structural parts, hoisting, braking and control devices, ropes or chains and fixing method; changes to the platform and arm are exempt if material, specification and size are unchanged","Only a change of the platform or the arm requires an alteration inspection, while changes to hoisting, braking and control devices, ropes or chains and the fixing method need mere recordation with drawings","Every alteration whatever requires an alteration inspection without exception, and on passing the agency must issue a brand new certificate with the valid period restarting at one year at most"],
 "Article 69."),

(L,"第70條",2,"吊籠-重新檢查",
 "吊籠停用超過檢查合格證有效期限一年以上擬恢復使用時，應如何辦理？",
 ["應填具重新檢查申請書申請重新檢查，合格者於原合格證記載檢查日期結果及有效期限最長一年","應填具重新檢查申請書申請重新檢查，合格者於原合格證記載檢查日期結果及有效期限最長二年","應由製造人重新辦理型式檢查及使用檢查後，始得由雇主申請恢復使用並重新核發合格證","應報請當地主管機關備查即得恢復使用，並於恢復使用後三個月內補辦定期檢查之手續"],"a",
 "第70條：雇主對於停用超過檢查合格證有效期限一年以上之吊籠，擬恢復使用時應填具重新檢查申請書向檢查機構申請重新檢查；合格者於原檢查合格證上記載檢查日期、檢查結果及使用有效期限，最長為一年；重新檢查準用第64條及第65條規定。",
 "How is a cradle idle over a year beyond its certificate's expiry brought back into use?",
 ["Apply for re-inspection; on passing, the original certificate is endorsed with date, result and a valid period of at most one year","Apply for re-inspection; on passing, the original certificate is endorsed with date, result and a valid period of at most two years","The maker must redo the type inspection and the use inspection before the employer may seek resumption and a new certificate","Recordation with the local competent authority permits resumption, the periodic inspection formalities following within three months"],
 "Article 70."),

(L,"第71條",2,"鍋爐-型式檢查",
 "鍋爐之製造或修改申請型式檢查時，應檢附載有哪些事項之書件？",
 ["型式構造詳圖及強度計算書、製造檢查設備之種類能力及數量、主任設計者與施工負責人學經歷概要、施工者資格及人數、以熔接者另附熔接人員資格證件與熔接程序規範及資格檢定紀錄","型式構造詳圖及強度計算書、工廠土地及建物權狀影本、公司近三年財務報表、勞工保險投保名冊、以熔接者另附熔接機廠牌型號及購置發票、油漆與防鏽塗料之出廠證明文件","設置場所平面圖及鍋爐房配置圖、燃料種類與年使用量、水處理藥劑清單、操作人員名冊及訓練證書、鍋爐房消防設備配置圖、空氣污染防制許可證及廢水排放許可文件","歷年檢查合格證影本、定期檢查結果報告表、內部檢查照片、超音波測厚紀錄、安全閥吹洩試驗紀錄、水壓試驗紀錄及非破壞檢查報告書等相關檢查文件之彙整資料"],"a",
 "第71條：鍋爐之製造或修改，製造人應於事前填具型式檢查申請書，檢附型式、構造詳圖及強度計算書、製造與檢查設備之種類能力及數量、主任設計者與施工負責人學經歷概要、施工者資格及人數，以熔接製造或修改者並應檢附熔接人員資格證件、熔接程序規範及熔接程序資格檢定紀錄；未經檢查合格不得製造或修改。",
 "What documents must accompany a boiler's type inspection application?",
 ["Type, detailed structural drawings and strength calculations, kinds, capacity and number of manufacturing and testing facilities, records of the chief designer and supervisor, welders' qualifications and numbers, plus welding credentials and procedure records","Type, detailed structural drawings and strength calculations, copies of the land and building titles, three years of financial statements, the labor insurance roster, plus the welding machine brand and invoice and paint certificates","Site plan and boiler house layout, kind and annual consumption of fuel, list of water treatment chemicals, operator roster and training certificates, boiler house fire equipment layout, air pollution permit and wastewater discharge papers","Copies of past inspection certificates, periodic inspection result reports, internal inspection photographs, ultrasonic thickness records, safety valve blow-off records, hydrostatic test records and non-destructive testing reports compiled together"],
 "Article 71."),

(L,"第72條",3,"鍋爐-品管品保",
 "鍋爐製造人之品管品保設備及人員規定，下列敘述何者正確？",
 ["施工負責人須大專機械科系畢業或機械技師具二年、高工機械科組畢業具五年或具八年以上經驗；衝床之設置以製造最高使用壓力超過每平方公分七公斤之鍋爐為限","施工負責人須大專機械科系畢業或機械技師具五年、高工機械科組畢業具八年或具十二年以上經驗；衝床之設置以製造最高使用壓力超過每平方公分十公斤之鍋爐為限","施工負責人得由製造人自行指派而無資格限制；衝床、退火爐及萬能試驗機等設備一律須自行購置，不得與其他事業單位共同設置或約定隨時利用之","施工負責人須具機械相關技師資格且有十年以上經驗；以熔接製造或修改者之施工者僅需具備三年以上相關工作經驗，無須取得熔接技術士之資格"],"a",
 "第72條：鍋爐製造人之主任設計者資格同第11條；施工負責人應為大專機械相關科系畢業或機械相關技師具二年以上、高工機械相關科組畢業具五年以上，或具八年以上實務經驗者；施工者以鉚接者須三年以上鉚接經驗、以熔接者須具熔接技術士資格、以鑄造者須三年以上鑄造經驗。衝床之設置以製造最高使用壓力超過每平方公分七公斤之鍋爐為限；退火爐以相關法規規定須實施退火者為限；部分設備能隨時利用或與其他事業單位共同設置者，得認定已具有。",
 "Which statement on a boiler maker's quality control facilities and personnel is correct?",
 ["The supervisor needs a mechanical degree or engineer licence plus two years, a vocational diploma plus five years, or eight years' experience; a press is required only for boilers above 7 kg/cm2","The supervisor needs a mechanical degree or engineer licence plus five years, a vocational diploma plus eight years, or twelve years' experience; a press is required only for boilers above 10 kg/cm2","The supervisor is freely appointed with no qualification requirement; presses, annealing furnaces and universal testing machines must all be owned and may never be shared or borrowed","The supervisor must be a licensed mechanical engineer with ten years' experience; a welder engaged in making or modifying needs only three years of work and no welding skills certificate"],
 "Article 72."),

(L,"第74條",2,"鍋爐-熔接檢查申請",
 "製造人申請鍋爐熔接檢查時，應檢附哪些書件？",
 ["材質證明一份、熔接明細表二份及施工位置分類圖一份、構造詳圖及強度計算書二份、熔接技術士資格證件、型式檢查合格證明與熔接程序規範及資格檢定紀錄影本各一份","材質證明三份、熔接明細表一份及設置場所平面圖二份、鍋爐房配置圖及基礎概要二份、操作人員名冊、水處理藥劑清單與燃燒裝置型錄影本各一份及廠商保固書","構造檢查合格戳記之鍋爐明細表二份、竣工檢查結果報告表一份、安全閥吹洩試驗紀錄、壓力表校正報告、給水裝置容量計算書及水位計配置圖各一份等相關文件","公司登記證明文件一份、工廠登記證影本二份、勞工保險投保名冊、職業安全衛生管理計畫、自動檢查計畫及緊急應變計畫各一份，並附最近一年財務報表"],"a",
 "第74條：製造人申請鍋爐之熔接檢查時，應填具鍋爐熔接檢查申請書，並檢附材質證明一份、熔接明細表二份及施工位置分類圖一份、構造詳圖及強度計算書二份、熔接施工人員之熔接技術士資格證件、製造設施型式檢查合格證明與熔接程序規範及熔接程序資格檢定紀錄等影本各一份。",
 "What documents must a maker attach when applying for a boiler's welding inspection?",
 ["One material certificate, two welding schedules and one work position classification chart, two sets of structural drawings and strength calculations, welders' certificates, and one copy each of the type certificate and welding procedure records","Three material certificates, one welding schedule and two site plans, two boiler house layouts with foundation outlines, the operator roster, the water chemical list, a burner catalogue copy and the supplier's warranty","Two boiler specification tables bearing the structural inspection stamp, one completion inspection result report, safety valve blow-off records, pressure gauge calibration reports, feedwater capacity calculations and water gauge layouts","One set of company registration documents, two copies of the factory registration, the labor insurance roster, the safety and health management plan, the automatic inspection plan and the emergency response plan, plus last year's accounts"],
 "Article 74."),

(L,"第75條",2,"鍋爐-熔接檢查程序",
 "檢查機構實施鍋爐熔接檢查之程序為何？",
 ["應就製造人檢附之書件先行審查合格後，再依熔接檢查項目實施現場實物檢查","應先實施現場實物檢查合格後，再就製造人檢附之書件實施書面審查以資確認","得僅就製造人檢附之書件實施書面審查即可，無須再實施任何現場實物之檢查","應由製造人自行實施現場實物檢查並作成紀錄，檢查機構僅辦理事後備查作業"],"a",
 "第75條：檢查機構實施鍋爐之熔接檢查時，應就製造人檢附之書件先行審查合格後，依熔接檢查項目實施現場實物檢查；實施現場實物檢查時，製造人或其指派人員應在，並應事前備妥機械性能試驗片及放射線檢查。第73條第2項：熔接檢查項目為材料檢查、外表檢查、熔接部之機械性能試驗、放射線檢查、熱處理檢查及其他必要檢查。",
 "What is the procedure for an inspection agency to conduct a boiler's welding inspection?",
 ["It first reviews and approves the documents the maker attached, then carries out the on-site physical inspection by the welding inspection items","It first carries out and passes the on-site physical inspection, then reviews the documents the maker attached in order to confirm them","It may confine itself to a documentary review of what the maker attached, with no on-site physical inspection needing to be carried out","The maker conducts the on-site physical inspection itself and records it, the agency merely handling the recordation afterwards"],
 "Article 75; see Article 73."),

(L,"第76條",2,"鍋爐-熔接合格證明",
 "鍋爐經熔接檢查合格者，檢查機構應如何處理？",
 ["在熔接明細表上加蓋熔接檢查合格戳記，檢查員簽章後交付申請人一份作為證明，並在被檢查物體明顯部位打印","發給鍋爐檢查合格證及熔接檢查結果報告表各一份，並在被檢查物體明顯部位張貼檢查合格標章以資識別","在鍋爐明細表上加蓋構造檢查合格戳記，檢查員簽章後交付申請人二份，並函報中央主管機關列管備查","由製造人自行於熔接明細表上註記合格並留存備查，檢查機構僅須將檢查結果通知申請人而無須打印"],"a",
 "第76條：鍋爐經熔接檢查合格者，檢查機構應在熔接明細表上加蓋熔接檢查合格戳記，檢查員簽章後交付申請人一份，做為熔接檢查合格證明，並應在被檢查物體上明顯部位打印，以資識別。第78條第1項第3款：申請構造檢查時，以熔接製造者應附加蓋熔接檢查合格戳記之熔接明細表。",
 "How does the agency handle a boiler that passes its welding inspection?",
 ["It stamps the welding schedule with the pass mark, the inspector signs, one copy is given to the applicant as proof, and the object is marked conspicuously","It issues one boiler inspection certificate and one welding inspection result report, and affixes a pass label conspicuously on the object for identification","It stamps the boiler specification table with the structural inspection pass mark, gives the applicant two copies, and reports it to the central authority","The maker notes the pass on the welding schedule itself and keeps it, the agency merely notifying the applicant without marking the object"],
 "Article 76."),

(L,"第78條",3,"鍋爐-構造檢查項目",
 "鍋爐構造檢查之項目包括下列何者？",
 ["施工方法、材料厚度、構造、尺寸、傳熱面積、最高使用壓力、強度計算審查、人孔、清掃孔、安全裝置之規劃、耐壓試驗及胴體端板管板煙管火室爐筒等使用之材料","安全閥數量容量及吹洩試驗、水位計數量位置、給水裝置容量數量、排水裝置容量數量、水處理裝置、鍋爐安全配置、鍋爐房設置、基礎出入口及燃燒裝置等項目","外觀檢查、外部之腐蝕裂痕變形污穢洩漏之檢測、必要時實施之非破壞檢查、易腐蝕處之定點超音波測厚、附屬品及附屬裝置檢查等以外部為主之相關檢查項目","材料檢查、外表檢查、熔接部之機械性能試驗、放射線檢查、熱處理檢查及其他必要之檢查等以熔接部品質為主之相關檢查項目，並由製造人備妥試驗片"],"a",
 "第78條第3項：鍋爐構造檢查項目為施工方法、材料厚度、構造、尺寸、傳熱面積、最高使用壓力、強度計算審查、人孔、清掃孔、安全裝置之規劃、耐壓試驗、胴體、端板、管板、煙管、火室、爐筒等使用之材料及其他必要之檢查。第82條第2項所列者為竣工檢查項目；第86條為外部檢查項目；第73條第2項為熔接檢查項目。",
 "What does a boiler's structural inspection cover?",
 ["Construction method, material thickness, structure, dimensions, heating surface, maximum working pressure, strength review, manholes, cleaning holes, safety device layout, pressure test and shell, end plate, tube plate, tube, furnace materials","Number and capacity of safety valves and blow-off testing, number and position of water gauges, capacity of feed and drain devices, water treatment, safe boiler layout, the boiler house, foundation, entrances and the burner installation","Visual inspection, detection of external corrosion, cracking, deformation, fouling and leakage, non-destructive testing where needed, spot ultrasonic thickness measurement at corrosion-prone points, and accessories and attachments","Material inspection, surface inspection, mechanical property testing of the weld, radiographic examination, heat treatment inspection and other necessary checks focused on weld quality, with test pieces prepared by the maker"],
 "Article 78, Paragraph 3."),

(L,"第79條",1,"鍋爐-構造檢查準備",
 "檢查機構實施鍋爐構造檢查時，製造人應事先備妥哪些事項？",
 ["將被檢查物件放置於易檢查位置，並準備水壓等耐壓試驗","將被檢查物件放置於易檢查位置，並準備機械性能試驗片","將被檢查物件加熱至常用溫度，並準備放射線檢查之設備","將被檢查物件完全分解為零件，並準備氣密試驗用之氣體"],"a",
 "第79條：檢查機構實施鍋爐之構造檢查時，製造人或其指派人員應在場，並應事先備妥將被檢查物件放置於易檢查位置、準備水壓等耐壓試驗。第90條第2項、第93條第2項：重新檢查及變更檢查準用第78條第3項及第79條規定。",
 "What must the maker prepare in advance for a boiler's structural inspection?",
 ["Place the object to be inspected where it is easy to inspect and prepare a hydrostatic or other pressure test","Place the object to be inspected where it is easy to inspect and prepare the mechanical property test pieces","Heat the object to be inspected up to its usual working temperature and prepare the radiographic testing gear","Dismantle the object to be inspected completely into parts and prepare the gas used for the airtightness test"],
 "Article 79."),

(L,"第80條",1,"鍋爐-構造合格證明",
 "鍋爐經構造檢查合格者，檢查機構應如何處理？",
 ["在鍋爐明細表上加蓋構造檢查合格戳記，檢查員簽章後交付申請人一份作為構造檢查合格證明，並在物體明顯部位打印","在熔接明細表上加蓋熔接檢查合格戳記，檢查員簽章後交付申請人二份作為構造檢查合格證明，並發給檢查合格證","直接發給鍋爐檢查合格證及竣工檢查結果報告表，其有效期限最長為一年，並由雇主置掛於鍋爐房之明顯處所","由製造人自行於鍋爐明細表註記構造檢查合格並留存備查，檢查機構僅需將檢查結果以書面通知申請人即可"],"a",
 "第80條：鍋爐經構造檢查合格者，檢查機構應在鍋爐明細表上加蓋構造檢查合格戳記，檢查員簽章後交付申請人一份，做為構造檢查合格證明，並應在被檢查物體上明顯部位打印，以資識別。第82條第1項第1款：申請竣工檢查時應檢附加蓋構造檢查或重新檢查合格戳記之鍋爐明細表。",
 "How does the agency handle a boiler that passes its structural inspection?",
 ["It stamps the boiler specification table with the structural pass mark, the inspector signs, one copy is given as proof, and the object is marked conspicuously","It stamps the welding schedule with the welding pass mark, the inspector signs, two copies are given as structural proof, and a certificate is issued","It directly issues the boiler inspection certificate and a completion inspection result report valid at most one year, posted in the boiler house","The maker notes the structural pass on the specification table itself and keeps it, the agency merely notifying the applicant of the result in writing"],
 "Article 80."),

(L,"第81條",1,"鍋爐-竣工檢查",
 "鍋爐設置完成時，雇主應辦理何事？未經竣工檢查合格有何限制？",
 ["應向檢查機構申請竣工檢查，未經竣工檢查合格不得使用；檢查機構實施竣工檢查時雇主或其指派人員應在場","應向檢查機構申請構造檢查，未經構造檢查合格不得設置；檢查機構實施構造檢查時製造人或其指派人應在場","應向中央主管機關申請型式檢查，未經型式檢查合格不得使用；檢查時原設計技師及施工負責人均應在場","應向當地主管機關報請備查，備查完成即可使用；嗣後於使用滿一年時再一併申請辦理竣工檢查及定期檢查"],"a",
 "第81條：雇主於鍋爐設置完成時，應向檢查機構申請竣工檢查；未經竣工檢查合格，不得使用。檢查機構實施竣工檢查時，雇主或其指派人員應在場。第82條：竣工檢查合格者，核發竣工檢查結果報告表及檢查合格證，有效期限最長為一年。",
 "What must an employer do when a boiler's installation is complete, and what if it has not passed?",
 ["Apply to the agency for a completion inspection; without passing it may not be used, and the employer or a designee must attend the inspection","Apply to the agency for a structural inspection; without passing it may not be installed, and the maker or a designee must attend the inspection","Apply to the central competent authority for a type inspection; without passing it may not be used, the designer and supervisor attending","File it with the local competent authority, after which use may begin, the completion and periodic inspections following after a year"],
 "Article 81."),

(L,"第82條",3,"鍋爐-竣工檢查項目",
 "鍋爐竣工檢查之項目及檢查合格證有效期限為何？",
 ["項目包括安全閥數量容量吹洩試驗、水位計數量位置、給水及排水裝置容量數量、水處理裝置、安全配置、鍋爐房設置、基礎出入口、安全裝置、壓力表數量尺寸及燃燒裝置；合格證有效期限最長一年","項目包括施工方法、材料厚度、構造尺寸、傳熱面積、最高使用壓力、強度計算審查、人孔清掃孔、安全裝置規劃及耐壓試驗等構造事項；合格證有效期限最長二年，並得由檢查機構延長","項目包括材料檢查、外表檢查、熔接部機械性能試驗、放射線檢查及熱處理檢查等熔接品質事項；合格證有效期限最長三年，惟發電用鍋爐得縮短為一年並與內部檢查同時辦理","項目包括外觀檢查、外部腐蝕裂痕變形污穢洩漏檢測、定點超音波測厚及附屬裝置檢查；合格證有效期限最長五年，並應由雇主每年自行實施外部檢查並作成紀錄留存"],"a",
 "第82條：鍋爐竣工檢查項目為安全閥數量、容量、吹洩試驗、水位計數量、位置、給水裝置之容量數量、排水裝置之容量數量、水處理裝置、鍋爐之安全配置、鍋爐房之設置、基礎、出入口、安全裝置、壓力表之數量尺寸、燃燒裝置及其他必要之檢查；經竣工檢查合格者核發鍋爐竣工檢查結果報告表及檢查合格證，有效期限最長為一年；雇主應將合格證或影本置掛於鍋爐房或作業場所明顯處。",
 "What does a boiler's completion inspection cover, and how long is the certificate valid?",
 ["Safety valve number, capacity and blow-off test, water gauges, feed and drain device capacity, water treatment, safe layout, boiler house, foundation, entrances, safety devices, pressure gauges and burner; valid at most one year","Construction method, material thickness, structure and dimensions, heating surface, maximum working pressure, strength review, manholes and cleaning holes, safety device layout and pressure testing; valid at most two years, extendable","Material inspection, surface inspection, mechanical property testing of welds, radiographic examination and heat treatment inspection; valid at most three years, though power boilers are cut to one year with internal inspection","Visual inspection, detection of external corrosion, cracking, deformation, fouling and leakage, spot ultrasonic thickness measurement and accessories; valid at most five years, with the employer inspecting externally each year"],
 "Article 82."),

(L,"第83條",1,"鍋爐-定期檢查申請",
 "雇主應於何時向檢查機構申請鍋爐之定期檢查？",
 ["應於鍋爐檢查合格證有效期限屆滿前一個月，填具定期檢查申請書向檢查機構申請","應於鍋爐檢查合格證有效期限屆滿前六個月，填具定期檢查申請書向檢查機構申請","應於鍋爐檢查合格證有效期限屆滿後一個月內，填具定期檢查申請書向檢查機構申請","應於鍋爐竣工檢查合格後每滿三年時，填具定期檢查申請書向中央主管機關提出申請"],"a",
 "第83條：雇主於鍋爐檢查合格證有效期限屆滿前一個月，應填具定期檢查申請書向檢查機構申請定期檢查。第84條：竣工檢查合格後第一次定期檢查應實施內、外部檢查；其後每年應實施外部檢查一次以上，內部檢查則視鍋爐種類每年或每二年一次以上。",
 "When must the employer apply for a boiler's periodic inspection?",
 ["One month before the boiler's inspection certificate expires, by filing a periodic inspection application with the agency","Six months before the boiler's inspection certificate expires, by filing a periodic inspection application with the agency","Within one month after the boiler's inspection certificate has expired, by filing a periodic inspection application","Every three years after the boiler passes its completion inspection, by applying to the central competent authority"],
 "Article 83; see Article 84."),

(L,"第85條",2,"鍋爐-內部檢查",
 "檢查機構受理鍋爐內部檢查時，應使雇主預先辦理何事？內部檢查項目為何？",
 ["應使其預先將鍋爐內部恢復常溫常壓、排放內容物、通風換氣、整理清掃內部；內部檢查項目為內部表面檢查及厚度腐蝕裂痕變形污穢等檢測、必要時之非破壞檢查與耐壓試驗","應使其預先將鍋爐加壓至最高使用壓力並保持高溫、封閉內容物；內部檢查項目為外觀檢查及外部腐蝕裂痕變形污穢洩漏之檢測、易腐蝕處之定點超音波測厚及附屬裝置檢查","應使其預先將鍋爐完全解體為零件並送交檢查機構；內部檢查項目為材料檢查、外表檢查、熔接部之機械性能試驗、放射線檢查及熱處理檢查等以熔接品質為主之項目","應使其預先備妥荷重試驗用荷物及吊掛器具；內部檢查項目為安全閥數量容量吹洩試驗、水位計數量位置、給水排水裝置容量數量及鍋爐房設置等配置事項之檢查"],"a",
 "第85條：檢查機構受理實施鍋爐內部檢查時，應將檢查日期通知雇主，使其預先將鍋爐之內部恢復至常溫、常壓、排放內容物、通風換氣、整理清掃內部及為其他定期檢查必要準備事項；內部檢查項目為鍋爐內部之表面檢查及厚度、腐蝕、裂痕、變形、污穢等之檢測，必要時實施之非破壞檢查、以檢查結果判定需要實施之耐壓試驗及其他必要之檢查。",
 "What must the employer prepare for a boiler's internal inspection, and what does that inspection cover?",
 ["Restore the interior to normal temperature and pressure, drain contents, ventilate and clean it; the check covers internal surfaces, thickness, corrosion, cracking, deformation and fouling, plus NDT and pressure testing as needed","Pressurise the boiler to its maximum working pressure and keep it hot with contents sealed in; the check covers appearance, external corrosion, cracking, deformation, fouling, leakage, spot thickness measurement and accessories","Dismantle the boiler entirely into parts and deliver them to the inspection agency; the check covers material and surface inspection, mechanical property testing of welds, radiographic examination and heat treatment","Prepare the loads and rigging gear for the load test; the check covers safety valve numbers and blow-off testing, water gauges, feed and drain device capacity and the layout of the boiler house itself"],
 "Article 85."),

(L,"第86條",2,"鍋爐-外部檢查",
 "鍋爐外部檢查之項目及超音波測厚之免除情形為何？",
 ["項目為外觀檢查、外部腐蝕裂痕變形污穢洩漏之檢測、必要時之非破壞檢查、易腐蝕處定點超音波測厚、附屬品及附屬裝置檢查；因特別高溫等致測厚確有困難者得免實施","項目為外觀檢查、外部腐蝕裂痕變形污穢洩漏之檢測、必要時之非破壞檢查、易腐蝕處定點超音波測厚、附屬品及附屬裝置檢查；超音波測厚於任何情形均不得免除實施","項目為內部表面檢查、厚度腐蝕裂痕變形污穢之檢測及耐壓試驗；因鍋爐內部空間狹小致人員無法進入者，得免實施超音波測厚並改以外觀檢查方式替代之","項目為安全閥吹洩試驗、壓力表校正、水位計檢查及燃燒裝置試運轉；因鍋爐停爐期間過短致無法降溫者，得免實施超音波測厚並由雇主自行檢測後備查"],"a",
 "第86條：鍋爐外部檢查之項目為外觀檢查、外部之腐蝕、裂痕、變形、污穢、洩漏之檢測、必要時實施之非破壞檢查、易腐蝕處之定點超音波測厚、附屬品及附屬裝置檢查；必要時得以適當儀器檢測其內部，發現有異狀者應併實施內部檢查；超音波測厚因特別高溫等致測厚確有困難者，得免實施。檢查機構受理外部檢查時應通知雇主，實施檢查時雇主或其指派人員應在場。",
 "What does a boiler's external inspection cover, and when may ultrasonic thickness measurement be waived?",
 ["Appearance, external corrosion, cracking, deformation, fouling and leakage, NDT where needed, spot ultrasonic thickness measurement at corrosion-prone points and accessories; waived where high temperature makes measuring genuinely difficult","Appearance, external corrosion, cracking, deformation, fouling and leakage, NDT where needed, spot ultrasonic thickness measurement at corrosion-prone points and accessories and attachments; that thickness measurement may never be waived at all","Internal surface inspection, detection of thickness, corrosion, cracking, deformation and fouling, and pressure testing; where the interior is too cramped to enter, thickness measurement is waived and replaced by visual checks","Safety valve blow-off testing, pressure gauge calibration, water gauge checks and burner trial running; where the shutdown is too short to cool down, thickness measurement is waived and the employer measures it itself"],
 "Article 86."),

(L,"第87條",2,"鍋爐-定期檢查效期",
 "鍋爐經定期檢查合格者，其使用有效期限最長為何？有無例外？",
 ["應於原檢查合格證上簽署註明使用有效期限，最長為一年；但依第84條第3項延長外部檢查期限者，最長得為二年","應於原檢查合格證上簽署註明使用有效期限，最長為二年；但發電用鍋爐一律縮短為一年，且不得再延長其期限","應重新核發檢查合格證並註明使用有效期限，最長為三年；但化工設備附屬鍋爐得由雇主自行延長至五年為限","應重新核發檢查合格證並註明使用有效期限，最長為五年；但經檢查機構認有必要時得縮短為三年並函知雇主"],"a",
 "第87條：檢查機構對定期檢查合格之鍋爐，應於原檢查合格證上簽署，註明使用有效期限，最長為一年；但第84條第3項（發電容量二萬瓩以上之發電用鍋爐外部檢查得延長並與內部檢查同時辦理）者，最長得為二年。檢查員並應填報鍋爐定期檢查結果報告表，將結果通知雇主。",
 "How long at most is a boiler valid after passing periodic inspection, and is there an exception?",
 ["The original certificate is endorsed for at most one year; where the external inspection interval is extended under Article 84(3) it may be at most two years","The original certificate is endorsed for a valid period of at most two years; power generating boilers are always cut to one year and may never be extended again","A new certificate is issued for at most three years; boilers attached to chemical plants may be extended by the employer itself up to five years","A new certificate is issued for at most five years; where the agency considers it necessary the period is shortened to three years and notified"],
 "Article 87; see Article 84."),

(L,"第88條",2,"鍋爐-不合格處理",
 "鍋爐經定期檢查不合格者，檢查員及檢查機構應如何處理？",
 ["檢查員應即於檢查合格證記事欄記載不合格情形並通知改善；情形嚴重有發生危害之虞者，應報請所屬檢查機構限制其最高使用壓力或禁止使用","檢查員應即註銷其檢查合格證並命令拆除該鍋爐；情形輕微者始得於檢查合格證記事欄記載不合格情形，並限期一個月內完成改善事項","檢查員應即函報中央主管機關裁處罰鍰；情形嚴重有發生危害之虞者，由中央主管機關逕行公告該事業單位名稱及不合格之具體情形","檢查員僅需口頭告知雇主不合格情形即可；是否限制最高使用壓力或禁止使用，由雇主視營運需要自行決定並作成紀錄留存備查"],"a",
 "第88條：鍋爐經定期檢查不合格者，檢查員應即於檢查合格證記事欄內記載不合格情形並通知改善；其情形嚴重有發生危害之虞者，並應報請所屬檢查機構限制其最高使用壓力或禁止使用。第一種壓力容器、高壓氣體特定設備、高壓氣體容器分別於第113條、第137條、第159條有相同規定。",
 "What must be done when a boiler fails its periodic inspection?",
 ["The inspector notes the failure in the remarks column of the certificate and calls for improvement; if serious enough to risk harm, the agency limits the working pressure or bans use","The inspector cancels the certificate at once and orders the boiler dismantled; only in slight cases is the failure noted in the remarks column with one month to improve","The inspector reports it to the central competent authority for a fine; if serious enough to risk harm, that authority publicly announces the undertaking's name and the defects","The inspector need only tell the employer orally; whether to limit the working pressure or stop use is for the employer to decide as its operations require and record"],
 "Article 88."),

(L,"第90條",2,"鍋爐-重新檢查申請",
 "所有人或雇主申請鍋爐重新檢查時，應檢附哪些書件？",
 ["鍋爐明細表二份、構造詳圖及強度計算書各二份（檢查機構認無必要者得免檢附）、前經檢查合格證明文件或其影本","鍋爐明細表一份、設置場所及周圍狀況圖二份、水處理紀錄、燃料使用量統計及操作人員名冊各一份等相關文件","熔接明細表二份及施工位置分類圖一份、熔接技術士資格證件、熔接程序規範及熔接程序資格檢定紀錄影本各一份","公司登記證明文件、工廠登記證影本、勞工保險投保名冊、自動檢查計畫及緊急應變計畫各一份等管理性質文件"],"a",
 "第90條：所有人或雇主申請鍋爐之重新檢查時，應填具鍋爐重新檢查申請書一份，並檢附鍋爐明細表二份、構造詳圖及強度計算書各二份（但檢查機構認無必要者得免檢附）、前經檢查合格證明文件或其影本；第78條第3項及第79條規定於重新檢查時準用之。第89條列有應申請重新檢查之六款情事。",
 "What documents must accompany an application for a boiler's re-inspection?",
 ["Two boiler specification tables, two sets each of detailed drawings and strength calculations (waivable if the agency finds them unnecessary), and the previous certificate or a copy","One boiler specification table, two drawings of the site and its surroundings, water treatment records, fuel consumption statistics and the operator roster, one copy each","Two welding schedules and one work position classification chart, the welders' skill certificates, and one copy each of the welding procedure specification and qualification records","The company registration documents, a copy of the factory registration, the labor insurance roster, the automatic inspection plan and the emergency response plan, one copy of each"],
 "Article 90; see Article 89."),

(L,"第91條",3,"鍋爐-重新檢查合格",
 "鍋爐經重新檢查合格者，檢查機構應如何處理？",
 ["在鍋爐明細表加蓋重新檢查合格戳記交付一份作為證明以辦理竣工檢查；但屬閒置後停用或經禁止使用而未遷移裝設者，得在原合格證記載並註明有效期限最長一年","在鍋爐明細表加蓋構造檢查合格戳記交付二份作為證明以辦理型式檢查；但屬外國進口者，得在原合格證記載檢查結果並註明使用有效期限最長為二年而免打印","直接核發新檢查合格證並註明使用有效期限最長為二年；凡經重新檢查合格者一律免再辦理竣工檢查，且外國進口者亦免於物體明顯部位打印識別","由所有人自行於鍋爐明細表註記重新檢查合格後留存備查；檢查機構僅須將檢查結果通知申請人，並由申請人逕行辦理竣工檢查而無須加蓋任何戳記"],"a",
 "第91條：鍋爐經重新檢查合格者，檢查機構應在鍋爐明細表上加蓋重新檢查合格戳記，檢查員簽章後交付申請人一份，做為重新檢查合格證明，以辦理竣工檢查；但符合第89條第2款之竣工檢查或定期檢查後停用或第3款（經禁止使用擬恢復使用），其未遷移裝設或遷移至廠內其他位置重新裝設，經檢查合格者，得在原檢查合格證上記載檢查日期、檢查結果及註明使用有效期限，最長為一年。外國進口者應在被檢查物體上明顯部位打印。",
 "How does the agency handle a boiler that passes re-inspection?",
 ["It stamps the specification table with the re-inspection pass mark and gives one copy as proof for the completion inspection; if idled or banned but not relocated, the original certificate is endorsed for at most one year","It stamps the specification table with the structural pass mark and gives two copies as proof for the type inspection; imported boilers may have the original certificate endorsed for at most two years without marking","It directly issues a new certificate valid at most two years; every boiler passing re-inspection is exempt from any completion inspection, and imported ones need not be marked conspicuously either","The owner notes the re-inspection pass on the specification table itself and keeps it; the agency merely notifies the applicant, who then proceeds to the completion inspection with no stamp at all"],
 "Article 91; see Article 89."),

(L,"第92條",3,"鍋爐-變更檢查",
 "鍋爐經修改致哪些部分變動時應申請變更檢查？修改達何種程度時應重辦型式檢查？",
 ["胴體集管器爐筒火室端板管板汽包頂蓋板或補強支撐、過熱器或節煤器、燃燒裝置、安裝基礎變動者應申請變更檢查；胴體或集管器修改達三分之一以上或爐筒火室端板管板全部修改者，應依第71條辦理","胴體集管器爐筒火室端板管板汽包頂蓋板或補強支撐、過熱器或節煤器、燃燒裝置、安裝基礎變動者應申請變更檢查；胴體或集管器修改達五分之一以上或爐筒火室端板管板半數修改者，應重辦竣工檢查","僅安全閥、壓力表、水位計或給水裝置變動者應申請變更檢查；胴體或集管器修改達二分之一以上或爐筒火室端板管板全部修改者，僅需檢附圖件報請檢查機構備查而無須重新辦理型式檢查","僅燃料種類或水處理方式變動者應申請變更檢查；不論胴體集管器爐筒火室端板管板修改達何種程度，均得於下次定期檢查時一併查核，無須另行申請變更檢查或重辦型式檢查"],"a",
 "第92條：鍋爐經修改致胴體、集管器、爐筒、火室、端板、管板、汽包、頂蓋板或補強支撐，或過熱器或節煤器，或燃燒裝置，或安裝基礎之一有變動者，所有人或雇主應申請變更檢查；變更檢查合格者，檢查員應在原檢查合格證記事欄內記載檢查日期、變更部分及檢查結果；鍋爐之胴體或集管器經修改達三分之一以上，或其爐筒、火室、端板或管板全部修改者，應依第71條規定（型式檢查）辦理。",
 "Which modifications require a boiler's alteration inspection, and when must the type inspection be redone?",
 ["Changes to shell, header, furnace, combustion chamber, end or tube plate, drum, cover plate or stays, superheater or economiser, burner, or foundation need an alteration inspection; a shell or header modified by a third or plates wholly replaced falls under Article 71","Changes to shell, header, furnace, combustion chamber, end or tube plate, drum, cover plate or stays, superheater or economiser, burner, or foundation need an alteration inspection; a shell or header modified by a fifth or half the plates means redoing the completion inspection","Only changes to safety valves, pressure gauges, water gauges or the feedwater device need an alteration inspection; a shell or header modified by a half or plates wholly replaced needs only drawings filed for recordation without any fresh type inspection at all","Only a change of fuel type or water treatment method needs an alteration inspection; however far the shell, header, furnace, chamber or plates are modified, it may be reviewed at the next periodic inspection with no separate application at all"],
 "Article 92."),

(L,"第93條",2,"鍋爐-變更檢查申請",
 "所有人或雇主申請鍋爐變更檢查時，應檢附哪些書件？",
 ["製造設施型式檢查合格證明、鍋爐明細表二份、變更部分圖件、構造詳圖及強度計算書各二份（檢查機構認無必要者得免）、前經檢查合格證明或其影本","製造設施型式檢查合格證明、熔接明細表二份、施工位置分類圖一份、熔接技術士資格證件、熔接程序規範及熔接程序資格檢定紀錄影本各一份等文件","設置場所及周圍狀況圖二份、鍋爐房消防設備配置圖、燃料使用量統計表、水處理紀錄、操作人員名冊及訓練證書影本各一份等現場管理文件","公司登記證明文件、工廠登記證影本、最近三年財務報表、勞工保險投保名冊、職業安全衛生管理計畫及自動檢查計畫各一份等行政管理文件"],"a",
 "第93條：所有人或雇主申請鍋爐變更檢查時，應填具鍋爐變更檢查申請書一份，並檢附製造設施型式檢查合格證明、鍋爐明細表二份、變更部分圖件、構造詳圖及強度計算書各二份（但檢查機構認無必要者得免檢附）、前經檢查合格證明或其影本；第78條第3項及第79條規定於變更檢查時準用之。",
 "What documents must accompany an application for a boiler's alteration inspection?",
 ["The facility type inspection certificate, two boiler specification tables, drawings of the altered part, two sets each of detailed drawings and strength calculations (waivable), and the previous certificate or a copy","The facility type inspection certificate, two welding schedules, one work position classification chart, the welders' skill certificates, and one copy each of the welding procedure specification and qualification records","Two drawings of the site and its surroundings, the boiler house fire equipment layout, fuel consumption statistics, water treatment records, and the operator roster with copies of training certificates","The company registration documents, a copy of the factory registration, three years of financial statements, the labor insurance roster, the safety and health management plan and the automatic inspection plan"],
 "Article 93."),

(L,"第94條",2,"鍋爐-必要措施",
 "檢查機構實施鍋爐各項檢查認有必要時，得告知所有人或雇主為哪些措施？",
 ["除去被檢查物體上被覆物之全部或一部、拔出鉚釘或管、在板上或管上鑽孔、鑄鐵鍋爐之解體及其他必要事項；鑽孔部分申請人得申請改以非破壞檢查","除去被檢查物體上被覆物之全部或一部、拔出鉚釘或管、在板上或管上鑽孔、鑄鐵鍋爐之解體及其他必要事項；惟各該措施均不得以非破壞檢查方式替代之","僅得要求除去被檢查物體上被覆物之全部或一部，其餘拔出鉚釘或管、鑽孔及解體等破壞性措施，均應報請中央主管機關逐案核准後始得為之","僅得要求雇主提供構造詳圖及強度計算書等文件供審查，不得要求為除去被覆物、拔出鉚釘或管、鑽孔或解體等任何影響設備完整性之措施"],"a",
 "第94條：檢查機構於實施鍋爐之構造檢查、竣工檢查、定期檢查、重新檢查或變更檢查認有必要時，得告知鍋爐所有人、雇主或其代理人為除去被檢查物體上被覆物之全部或一部、拔出鉚釘或管、在板上或管上鑽孔、鑄鐵鍋爐之解體及其他認為必要事項；其中鑽孔部分，申請人得申請改以非破壞檢查，並提出證明文件。第119條就第一種壓力容器有類似規定（含熱交換器之分解）。",
 "What measures may an agency require of a boiler's owner or employer when it deems them necessary?",
 ["Removing all or part of the covering, drawing out rivets or tubes, drilling holes in plates or tubes, dismantling a cast iron boiler and other necessary steps; drilling may be replaced by NDT on application","Removing all or part of the covering, drawing out rivets or tubes, drilling holes in plates or tubes, dismantling a cast iron boiler and other necessary steps; none of these may be replaced by NDT","Only removal of all or part of the covering may be required; drawing out rivets or tubes, drilling and dismantling all need case-by-case approval of the central competent authority","Only production of detailed drawings and strength calculations for review may be required; no removal of covering, drawing of rivets, drilling or dismantling may ever be demanded"],
 "Article 94; cf. Article 119."),

(L,"第95條",2,"第一種壓力容器-型式檢查",
 "第一種壓力容器之製造或修改，其型式檢查申請書應檢附哪些事項之書件？",
 ["型式構造詳圖及強度計算書、製造檢查設備之種類能力及數量、主任設計者與施工負責人學經歷概要、施工者資格及人數、以熔接者另附熔接人員資格證件與熔接程序規範及資格檢定紀錄","型式構造詳圖及強度計算書、設置場所及周圍狀況圖、內容物種類及最高使用壓力申報表、安全閥吹洩量計算書、操作人員名冊及訓練證書影本、緊急應變計畫及自動檢查計畫","工廠登記證及公司登記證明文件、最近三年財務報表、勞工保險投保名冊、職業安全衛生管理計畫、承攬商管理辦法、教育訓練紀錄及健康檢查紀錄等行政管理性質之文件資料","歷次檢查合格證影本及定期檢查結果報告表、內部檢查照片、超音波測厚紀錄、耐壓試驗紀錄、氣密試驗紀錄及非破壞檢查報告書等歷史檢查文件之彙整資料與說明"],"a",
 "第95條：第一種壓力容器之製造或修改，製造人應於事前填具型式檢查申請書，檢附型式、構造詳圖及強度計算書、製造與檢查設備之種類能力及數量、主任設計者與施工負責人學經歷概要、施工者資格及人數，以熔接製造或修改者並應檢附熔接人員資格證件、熔接程序規範及熔接程序資格檢定記錄；未經檢查合格不得製造或修改。",
 "What documents must accompany a type inspection application for a Class 1 pressure vessel?",
 ["Type, detailed drawings and strength calculations, kinds, capacity and number of manufacturing and testing facilities, records of the chief designer and supervisor, welders' qualifications and numbers, plus welding credentials and procedure records","Type, detailed drawings and strength calculations, drawings of the site and its surroundings, a declaration of the contents and the maximum working pressure, safety valve blow-off calculations, the operator roster with training records, and the emergency response plan","The factory and company registration documents, three years of financial statements, the labor insurance roster, the safety and health management plan, contractor management rules, training records and health examination records","Copies of past inspection certificates and periodic result reports, internal inspection photographs, ultrasonic thickness records, pressure test records, airtightness test records and non-destructive testing reports compiled together"],
 "Article 95."),

(L,"第96條",3,"第一種壓力容器-挖製",
 "以整塊材料挖製之第一種壓力容器，其製造設備及人員規定為何？",
 ["主任設計者仍適用第72條規定；製造及檢查設備應具備挖製裝置及水壓試驗設備；施工負責人須大專機械科系畢業或技師具一年、高工機械科組畢業具二年或具五年以上經驗；施工者須二年以上挖製經驗","主任設計者及施工負責人均免資格限制；製造及檢查設備應具備彎板機、熔接機、衝床、退火爐、萬能試驗機、水壓試驗設備及放射線檢查設備；施工者須具備熔接技術士資格並有五年以上實務經驗","主任設計者仍適用第72條規定；製造及檢查設備應具備鍛造設備、底部接合設備、退火爐、洗滌設備及確認厚度之器具；施工負責人須具機械技師資格；施工者須具五年以上鑄造相關工作之實務經驗","主任設計者須具機械技師資格；製造及檢查設備得完全免除而以委外檢驗替代；施工負責人須大專機械科系畢業具五年、高工機械科組畢業具八年或具十二年以上經驗；施工者則須具三年以上鉚接經驗"],"a",
 "第96條：第一種壓力容器之製造，除整塊材料挖製者外，品管品保之設備及人員準用第72條規定；以整塊材料挖製者，除主任設計者仍適用第72條第1項第2款外，其設備及人員應為：製造及檢查設備具備挖製裝置及水壓試驗設備；施工負責人為大專機械相關科系畢業或機械相關技師具一年以上、高工機械相關科組畢業具二年以上，或具五年以上實務經驗者；施工者應具從事相關挖製工作二年以上經驗。",
 "What facility and personnel rules apply to a Class 1 pressure vessel bored from a solid block?",
 ["The chief designer still follows Article 72; boring equipment and hydrostatic test facilities are needed; the supervisor needs a mechanical degree or licence plus one year, a vocational diploma plus two years, or five years; the worker needs two years of boring work","Neither chief designer nor supervisor needs qualifications; plate bending machines, welders, presses, annealing furnaces, universal testing machines, hydrostatic test and radiographic facilities are needed; the worker needs a welding certificate and five years","The chief designer still follows Article 72; forging equipment, bottom joining equipment, an annealing furnace, washing equipment and thickness gauges are needed; the supervisor must be a licensed engineer; the worker needs five years of casting work","The chief designer must hold an engineer licence; manufacturing and testing facilities may be dispensed with entirely and outsourced; the supervisor needs a degree plus five years, a diploma plus eight, or twelve years; the worker needs three years of riveting"],
 "Article 96."),

(L,"第97條",2,"第一種壓力容器-熔接檢查",
 "以熔接製造之第一種壓力容器，何種情形得免申請熔接檢查？",
 ["附屬設備或僅對不產生壓縮應力以外之應力部分施以熔接者；或僅就內徑三百公厘以下之管之圓周接頭、加強材料管管台凸緣閥座熔接於胴體端板、支持架等不承受壓力物件之熔接及防漏熔接者","附屬設備或僅對產生壓縮應力部分施以熔接者；或僅就內徑五百公厘以下之管之圓周接頭、加強材料管管台凸緣閥座熔接於胴體端板、支持架等承受壓力物件之熔接及防漏熔接者，均得免申請","凡以熔接製造之第一種壓力容器均應申請熔接檢查而無任何例外；但檢查機構認有必要時，得要求製造人另行實施非破壞檢查、熱處理檢查及熔接部之機械性能試驗等項目","凡最高使用壓力未超過每平方公分十公斤或內容積未超過一立方公尺者，均得免申請熔接檢查；其餘情形則應於製造完成後併同構造檢查一併申請辦理熔接檢查"],"a",
 "第97條：以熔接製造之第一種壓力容器應於施工前由製造人向製造所在地檢查機構申請熔接檢查；但附屬設備或僅對不產生壓縮應力以外之應力部分施以熔接者，或僅就內徑三百公厘以下之管之圓周接頭、加強材料管管台凸緣及閥座等熔接在胴體或端板上、支持架或其他不承受壓力物件熔接於胴體端板、防漏熔接等部分施以熔接者，不在此限。熔接檢查項目為材料檢查、外表檢查、熔接部之機械性能試驗、放射線檢查、熱處理檢查及其他必要之檢查。",
 "When is a welded Class 1 pressure vessel exempt from applying for a welding inspection?",
 ["Where only accessories or parts bearing stresses other than compressive are welded; or where welding is confined to circumferential joints of pipes up to 300 mm bore, reinforcements, nozzles, flanges and valve seats on shells or end plates, supports and seal welds","Where only accessories or parts bearing compressive stress are welded; or where the welding is confined to circumferential joints of pipes up to 500 mm bore, reinforcing materials, nozzles, flanges and valve seats, pressure-bearing supports and every seal weld","Every welded Class 1 pressure vessel must apply for welding inspection with no exception; the agency may however require the maker to add non-destructive testing, heat treatment inspection and mechanical property testing of the weld","Any vessel whose maximum working pressure is not over 10 kg/cm2 or whose volume is not over one cubic metre is exempt; otherwise the welding inspection is applied for together with the structural inspection after manufacture"],
 "Article 97."),

(L,"第98條",2,"第一種壓力容器-熔接申請",
 "製造人申請第一種壓力容器熔接檢查時，應檢附哪些書件？",
 ["材質證明一份、熔接明細表二份及施工位置分類圖一份、構造詳圖及強度計算書各二份、熔接技術士資格證件、型式檢查合格證明與熔接程序規範及資格檢定紀錄影本各一份","材質證明二份、設置場所及周圍狀況圖一份、內容物種類申報表、安全閥吹洩量計算書、壓力表校正報告及操作人員名冊各一份，並附最近一次定期檢查結果報告表","加蓋構造檢查合格戳記之明細表二份、竣工檢查結果報告表一份、耐壓試驗紀錄、氣密試驗紀錄及非破壞檢查報告書各一份，並附前經檢查合格證明文件影本","公司登記證明文件、工廠登記證影本、勞工保險投保名冊、職業安全衛生管理計畫、自動檢查計畫及緊急應變計畫各一份，並附最近三年之財務報表資料"],"a",
 "第98條：製造人申請第一種壓力容器之熔接檢查時，應填具熔接檢查申請書並檢附材質證明一份、熔接明細表二份及施工位置分類圖一份、構造詳圖及強度計算書各二份、熔接施工人員之熔接技術士資格證件、製造設施型式檢查合格證明與熔接程序規範及熔接程序資格檢定紀錄等影本各一份。",
 "What documents must accompany a welding inspection application for a Class 1 pressure vessel?",
 ["One material certificate, two welding schedules and one work position chart, two sets each of detailed drawings and strength calculations, welders' certificates, and one copy each of the type certificate and welding procedure records","Two material certificates, one drawing of the site and surroundings, a declaration of contents, safety valve blow-off calculations, a pressure gauge calibration report and the operator roster, plus the latest periodic result report","Two specification tables bearing the structural inspection stamp, one completion inspection result report, pressure test records, airtightness test records and a non-destructive testing report, plus a copy of the previous certificate","The company registration documents, a copy of the factory registration, the labor insurance roster, the safety and health management plan, the automatic inspection plan and the emergency response plan, plus three years of accounts"],
 "Article 98."),

(L,"第99條",1,"第一種壓力容器-熔接程序",
 "檢查機構實施第一種壓力容器熔接檢查之現場實物檢查時，製造人應事前備妥何事項？",
 ["製造人或其指派人員應在場，並應事前備妥機械性能試驗片及放射線檢查","製造人或其指派人員應在場，並應事前備妥水壓試驗設備及退火爐設備","雇主或其指派人員應在場，並應事前備妥荷重試驗用荷物及吊掛之器具","所有人或其代理人應在場，並應事前備妥氣密試驗用氣體及絕熱材料等"],"a",
 "第99條：檢查機構實施第一種壓力容器之熔接檢查時，應就製造人檢附之書件先行審查合格後，依熔接檢查項目實施現場實物檢查；實施現場實物檢查時，製造人或其指派人員應在場，並應事前備妥機械性能試驗片及放射線檢查。鍋爐之熔接檢查（第75條）亦同。",
 "For the on-site part of a Class 1 pressure vessel welding inspection, what must the maker prepare?",
 ["The maker or a designee must attend, and mechanical property test pieces and radiographic examination must be prepared beforehand","The maker or a designee must attend, and hydrostatic testing equipment and an annealing furnace must be prepared beforehand","The employer or a designee must attend, and the loads for the load test and the necessary rigging gear must be prepared","The owner or an agent must attend, and the gas for the airtightness test and insulating materials must be prepared beforehand"],
 "Article 99; cf. Article 75."),

(L,"第100條",1,"第一種壓力容器-熔接合格",
 "第一種壓力容器經熔接檢查合格者，檢查機構應如何處理？",
 ["在熔接明細表上加蓋熔接檢查合格戳記，檢查員簽章後交付申請人一份作為熔接檢查合格證明，並在物體明顯部位打印","在壓力容器明細表上加蓋構造檢查合格戳記，檢查員簽章後交付申請人二份作為熔接檢查合格證明，並發給合格證","逕行核發第一種壓力容器檢查合格證及竣工檢查結果報告表，其有效期限最長為一年，並由雇主置掛於作業場所","由製造人自行於熔接明細表註記熔接檢查合格後留存備查，檢查機構僅須以書面將檢查結果通知申請人即可"],"a",
 "第100條：第一種壓力容器經熔接檢查合格者，檢查機構應在熔接明細表上加蓋熔接檢查合格戳記，檢查員簽章後交付申請人一份，做為熔接檢查合格證明，並應在被檢查物體上明顯部位打印，以資識別。第102條第1項第3款：申請構造檢查時，以熔接製造者應附加蓋熔接檢查合格戳記之熔接明細表。",
 "How does the agency handle a Class 1 pressure vessel that passes its welding inspection?",
 ["It stamps the welding schedule with the welding pass mark, the inspector signs, one copy is given as proof, and the object is marked conspicuously","It stamps the vessel specification table with the structural pass mark, the inspector signs, two copies are given as proof, and a certificate is issued","It directly issues the vessel inspection certificate and a completion inspection result report valid at most one year, posted at the workplace","The maker notes the welding pass on the welding schedule itself and keeps it, the agency merely notifying the applicant of the result in writing"],
 "Article 100."),
]
